 * Runs the instant-runoff count for a parsed election and yields the
 * per-round results as they are decided.
 */

/**
 * Picks which of several tied-for-fewest candidates to eliminate. Compares
 * their vote counts round by round, from the first round onwards, keeping
 * only those tied for fewest at the first round that separates them and
 * restarting the comparison from the first round with the survivors. When no
 * round separates them, the one whose name sorts last by code point is
 * eliminated.
 */
function breakTie(tied, roundHistory) {
  let candidates = tied
  for (let i = 0; i < roundHistory.length; i++) {
    if (candidates.length === 1) break
    const votes = roundHistory[i]
    const values = candidates.map((c) => votes.get(c))
    const min = Math.min(...values)
    if (!values.every((v) => v === min)) {
      candidates = candidates.filter((c) => votes.get(c) === min)
      i = -1
    }
  }
  if (candidates.length === 1) return candidates[0]
  return candidates.slice().sort().at(-1)
}

/**
 * Runs the full count. `onRound` is called after each round is tallied with
 * `{ votes, exhausted, eliminated, winner }`, where `votes` is a Map from
 * every continuing candidate to its vote count for that round, sorted by
 * descending votes and then ascending name, and exactly one of `eliminated`
 * or `winner` is set once the round decides the election's next step (or
 * neither, when the round ends with no winner).
 */
export function runElection({ candidates, ballots }, onRound) {
  let continuing = candidates.slice()
  const roundHistory = []
  let winner = null

  for (;;) {
    const tally = new Map(continuing.map((c) => [c, 0]))
    let exhausted = 0
    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => tally.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        tally.set(choice, tally.get(choice) + ballot.count)
      }
    }

    roundHistory.push(tally)

    const sorted = continuing.slice().sort((a, b) => {
      const diff = tally.get(b) - tally.get(a)
      return diff !== 0 ? diff : a < b ? -1 : a > b ? 1 : 0
    })
    const votes = new Map(sorted.map((c) => [c, tally.get(c)]))

    const activeTotal = continuing.reduce((sum, c) => sum + tally.get(c), 0)

    let eliminated = null
    if (activeTotal > 0) {
      for (const c of continuing) {
        if (tally.get(c) * 2 > activeTotal) {
          winner = c
          break
        }
      }
    }

    if (winner === null && activeTotal > 0) {
      const min = Math.min(...continuing.map((c) => tally.get(c)))
      const tied = continuing.filter((c) => tally.get(c) === min)
      eliminated = tied.length === 1 ? tied[0] : breakTie(tied, roundHistory)
      continuing = continuing.filter((c) => c !== eliminated)
    }

    onRound({ votes, exhausted, eliminated, winner })

    if (winner !== null || activeTotal === 0) return
  }
}
"}

